<?php
namespace App\Modules\Orders\Application;
use App\Modules\Orders\Application\Data\CreateProductionFromDemandData;use App\Modules\Orders\Domain\Enums\ProductionDemandStatus;use App\Modules\Orders\Domain\Enums\SalesOrderStatus;use App\Modules\Orders\Domain\Models\ProductionDemand;use App\Modules\Production\Application\Data\PlannedOutputData;use App\Modules\Production\Application\Data\PlanProductionData;use App\Modules\Production\Application\PlanProduction;use DomainException;use Illuminate\Support\Facades\DB;
class CreateProductionFromDemand {public function __construct(private readonly PlanProduction $plan){}public function execute(CreateProductionFromDemandData $data){return DB::transaction(function()use($data){$demands=ProductionDemand::query()->with('orderLine.order')->whereIn('id',$data->demandIds)->lockForUpdate()->get();if($demands->count()!==count(array_unique($data->demandIds))||$demands->isEmpty())throw new DomainException('Selecciona demandas pendientes válidas.');if($demands->contains(fn($d)=>$d->status!==ProductionDemandStatus::Pending))throw new DomainException('Alguna demanda ya fue planificada.');$versionIds=$demands->pluck('recipe_version_id')->unique();if($versionIds->count()!==1)throw new DomainException('Solo pueden consolidarse pedidos de la misma versión de masa.');$suggested=$demands->reduce(fn($sum,$d)=>bcadd($sum,$d->suggested_flour_quantity,6),'0');$flour=$data->flourQuantityKg?:$suggested;if(bccomp($flour,'0',6)<=0)throw new DomainException('La harina sugerida o manual debe ser positiva.');$outputs=$demands->groupBy('recipe_compatible_product_id')->map(fn($group,$id)=>new PlannedOutputData($id,$group->reduce(fn($sum,$d)=>bcadd($sum,$d->pending_quantity,6),'0')))->values()->all();$production=$this->plan->execute(new PlanProductionData($versionIds->first(),$data->plannedFor,$flour,$data->laborMethod,$data->responsiblePersonId,$data->actor,$outputs));foreach($demands as $demand){$production->orderAllocations()->create(['sales_order_line_id'=>$demand->sales_order_line_id,'planned_quantity'=>$demand->pending_quantity]);$demand->update(['status'=>ProductionDemandStatus::Planned]);$order=$demand->orderLine->order;if($order->status===SalesOrderStatus::PendingProduction){$order->update(['status'=>SalesOrderStatus::InProduction]);$order->histories()->create(['from_status'=>SalesOrderStatus::PendingProduction->value,'to_status'=>SalesOrderStatus::InProduction->value,'changed_by'=>$data->actor->id,'changed_at'=>now(),'notes'=>"Vinculado a {$production->document_number}."]);}}return $production->fresh('orderAllocations');});}}
